import 'package:flutter/material.dart';

/// DearCocoa: manual card creation registry (v0.3.5).
///
/// Memex renders 22 card templates, but before v0.3.5 only Note/Task/Rating
/// were creatable without AI. This registry describes every template a user
/// can fill manually with the "+" composer, one field list per template.
/// The AI-related templates (insight_summary, cross-record insight cards)
/// are deliberately NOT creatable here — they are generated by the agent.
///
/// The data keys mirror the widget constructors in
/// `lib/ui/core/cards/templates/**` so `NativeCardFactory.build` renders them.

enum TemplateFieldType {
  /// Single-line text.
  text,

  /// Multi-line text.
  multiline,

  /// Numeric value (double).
  number,

  /// Integer value (int).
  int,

  /// 1..5 star picker (stores int).
  stars,

  /// 1..5 mood faces picker (stores int).
  mood,

  /// Single image picker (stores `fs://<name>` or passthrough URL).
  image,

  /// Multi image picker (stores list of `fs://<name>`).
  images,

  /// Date + time picker (stores ISO-8601 local string).
  datetime,

  /// Dynamic list of single-line strings.
  listText,

  /// Dynamic key/value rows (stores Map<String, String>).
  kv,
}

class TemplateField {
  final String key;
  final String label;
  final TemplateFieldType type;
  final bool required;
  final Object? initial;
  final String? hint;

  const TemplateField(
    this.key,
    this.label,
    this.type, {
    this.required = false,
    this.initial,
    this.hint,
  });
}

class TemplateSpec {
  final String templateId;
  final String label;
  final String category;
  final IconData icon;
  final String? defaultTitleKey;
  final List<TemplateField> fields;

  const TemplateSpec({
    required this.templateId,
    required this.label,
    required this.category,
    required this.icon,
    required this.fields,
    this.defaultTitleKey = 'title',
  });
}

