/// Look up a creatable template by id.
TemplateSpec? findTemplateSpec(String templateId) {
  for (final s in kCreatableTemplates) {
    if (s.templateId == templateId) return s;
  }
  return null;
}

/// Turn free-text list items into structured template data.
///
/// Supported mini-syntax per row:
///  - "Name: 42 unit"  -> {title, value, unit}     (metric items)
///  - "Name: 9.90"     -> {name, price}            (transaction items)
///  - "Name: text"     -> {author/role, text}      (conversation messages)
/// Falls back to raw text in the primary field when no separator is found.
List<Map<String, dynamic>> parseColonList(
  List<String> rows,
  String keyA,
  String keyB,
) {
  final out = <Map<String, dynamic>>[];
  for (final raw in rows) {
    final line = raw.trim();
    if (line.isEmpty) continue;
    final idx = line.indexOf(':');
    if (idx > 0) {
      out.add({
        keyA: line.substring(0, idx).trim(),
        keyB: line.substring(idx + 1).trim(),
      });
    } else {
      out.add({keyA: line, keyB: ''});
    }
  }
  return out;
}

/// Build the template `uiConfigs[0].data` map from the composer form values.
Map<String, dynamic> buildTemplateData(
  TemplateSpec spec,
  Map<String, dynamic> v,
) {
  switch (spec.templateId) {
    case 'snippet':
      return {'text': v['text'] ?? '', 'style': 'default'};
    case 'article':
      return {
        'title': v['title'] ?? '',
        'body': v['body'] ?? '',
        if ((v['image_url'] as String? ?? '').isNotEmpty)
          'image_url': v['image_url'],
      };
    case 'quote':
      return {
        'content': v['content'] ?? '',
        if ((v['author'] as String? ?? '').isNotEmpty) 'author': v['author'],
        if ((v['source'] as String? ?? '').isNotEmpty) 'source': v['source'],
      };
    case 'link':
      return {
        'url': v['url'] ?? '',
        'title': v['title'] ?? '',
        'description': v['description'] ?? '',
      };
    case 'conversation':
      return {
        'title': v['title'] ?? '',
        'messages': parseColonList(
          (v['messages'] as List?)?.cast<String>() ?? const [],
          'name',
          'text',
        ),
      };
    case 'metric':
      return {
        'title': v['title'] ?? '',
        'items': [
          for (final m in parseColonList(
            (v['items'] as List?)?.cast<String>() ?? const [],
            'title',
            'value',
          ))
            {
              'title': m['title'],
              'value': num.tryParse('${m['value']}') ?? 0,
              'unit': '',
              'color': 'indigo',
            },
        ],
      };
    case 'rating':
      return {
        'subject': v['subject'] ?? '',
        'score': v['score'] ?? 4,
        'max_score': 5,
        if ((v['comment'] as String? ?? '').isNotEmpty) 'comment': v['comment'],
      };
    case 'mood':
      final moods = const ['Very low', 'Low', 'Okay', 'Good', 'Great'];
      final idx = ((v['mood'] as int?) ?? 3).clamp(1, 5);
      return {
        'mood': idx,
        'mood_name': moods[idx - 1],
        'intensity': v['intensity'] ?? 5,
        if ((v['trigger'] as String? ?? '').isNotEmpty) 'trigger': v['trigger'],
      };
    case 'transaction':
      return {
        'merchant': v['merchant'] ?? '',
        'amount': v['amount'] ?? '0.00',
        'location': v['location'] ?? 'Online',
        'items': [
          for (final m in parseColonList(
            (v['items'] as List?)?.cast<String>() ?? const [],
            'name',
            'price',
          ))
            {'name': m['name'], 'price': m['price']},
        ],
      };
    case 'spec_sheet':
      return {
        'title': v['title'] ?? '',
        if ((v['subtitle'] as String? ?? '').isNotEmpty)
          'subtitle': v['subtitle'],
        if ((v['image_url'] as String? ?? '').isNotEmpty)
          'image_url': v['image_url'],
        'specs': v['specs'] ?? <String, String>{},
      };
    case 'person':
      return {
        'name': v['name'] ?? '',
        if ((v['relation'] as String? ?? '').isNotEmpty)
          'relation': v['relation'],
        if ((v['status'] as String? ?? '').isNotEmpty) 'status': v['status'],
        if ((v['image_url'] as String? ?? '').isNotEmpty)
          'image_url': v['image_url'],
      };
    case 'place':
      return {
        'name': v['name'] ?? '',
        'address': v['address'] ?? '',
        if (v['latitude'] != null) 'latitude': v['latitude'],
        if (v['longitude'] != null) 'longitude': v['longitude'],
      };
    case 'compact':
      return {
        'title': v['title'] ?? '',
        'summary': v['summary'] ?? '',
      };
    case 'snapshot':
      return {
        'image_url': v['image_url'] ?? '',
        'caption': v['caption'] ?? '',
      };
    case 'gallery':
      return {
        'image_urls': (v['image_urls'] as List?)?.cast<String>() ?? const [],
        'title': v['title'] ?? '',
      };
    case 'event':
      return {
        'title': v['title'] ?? '',
        'start_time': v['start_time'] ?? '',
        if ((v['end_time'] as String? ?? '').isNotEmpty)
          'end_time': v['end_time'],
        if ((v['location'] as String? ?? '').isNotEmpty)
          'location': v['location'],
      };
    case 'duration':
      return {
        'title': v['title'] ?? '',
        'elapsed': (v['elapsed'] as num?)?.toInt() ?? 0,
        'remaining': 0,
        'completion_count': (v['completion_count'] as num?)?.toInt() ?? 1,
        'is_running': false,
      };
    case 'task':
      return {
        'title': v['title'] ?? '',
        'subtasks': [
          for (final t in (v['subtasks'] as List?)?.cast<String>() ?? const [])
            if (t.trim().isNotEmpty) {'title': t.trim(), 'completed': false},
        ],
        'is_completed': false,
      };
    case 'routine':
      return {
        'habit_name': v['habit_name'] ?? '',
        'streak': (v['streak'] as num?)?.toInt() ?? 0,
        'history': <bool>[],
      };
    case 'progress':
      return {
        'title': v['title'] ?? '',
        'current': (v['current'] as num?)?.toDouble() ?? 0,
        'total': (v['total'] as num?)?.toDouble() ?? 100,
        'unit': v['unit'] ?? '%',
        'label': v['label'] ?? '',
      };
    case 'procedure':
      return {
        'title': v['title'] ?? '',
        'steps': (v['steps'] as List?)?.cast<String>() ?? const [],
      };
    default:
      return Map<String, dynamic>.from(v);
  }
}

/// Best human title for the record from the filled values.
String templateRecordTitle(TemplateSpec spec, Map<String, dynamic> data) {
  switch (spec.templateId) {
    case 'snippet':
      final text = '${data['text'] ?? ''}';
      final first = text.split('\n').first.trim();
      return first.length > 60 ? '${first.substring(0, 60)}…' : first;
    case 'quote':
      final c = '${data['content'] ?? ''}';
      final first = c.split('\n').first.trim();
      return first.length > 60 ? '${first.substring(0, 60)}…' : first;
    case 'mood':
      return '${data['mood_name'] ?? 'Mood'}';
    case 'rating':
      return '${data['subject'] ?? 'Rating'}';
    case 'transaction':
      return '${data['merchant'] ?? 'Transaction'}';
    case 'person':
      return '${data['name'] ?? 'Person'}';
    case 'place':
      return '${data['name'] ?? 'Place'}';
    case 'snapshot':
    case 'gallery':
      final cap = '${data['caption'] ?? data['title'] ?? ''}';
      return cap.isEmpty ? spec.label : cap;
    case 'routine':
      return '${data['habit_name'] ?? 'Routine'}';
    case 'metric':
    case 'event':
    case 'duration':
    case 'progress':
    case 'procedure':
    case 'task':
    case 'article':
    case 'link':
    case 'conversation':
    case 'spec_sheet':
    case 'compact':
    default:
      final t = '${data[spec.defaultTitleKey ?? 'title'] ?? ''}';
      return t.isEmpty ? spec.label : t;
  }
}

/// Plain-text fact content (KB + rawText) from the filled values.
String templateRecordFact(TemplateSpec spec, Map<String, dynamic> data) {
  final buf = StringBuffer();
  switch (spec.templateId) {
    case 'task':
      for (final s
          in (data['subtasks'] as List?)?.cast<Map>() ?? const <Map>[]) {
        buf.writeln('- [ ] ${s['title']}');
      }
      return buf.toString().trim();
    case 'procedure':
      var i = 1;
      for (final s
          in (data['steps'] as List?)?.cast<String>() ?? const <String>[]) {
        buf.writeln('$i. $s');
        i++;
      }
      return buf.toString().trim();
    case 'metric':
      for (final m
          in (data['items'] as List?)?.cast<Map>() ?? const <Map>[]) {
        buf.writeln('- ${m['title']}: ${m['value']}');
      }
      return buf.toString().trim();
    default:
      for (final f in spec.fields) {
        final value = data[f.key];
        if (value == null || value.toString().isEmpty) continue;
        if (value is List) continue;
        if (value is Map) continue;
        buf.writeln('${f.label}: $value');
      }
      return buf.toString().trim();
  }
}
